create table if not exists public.fleet_route_updates (id uuid primary key default gen_random_uuid(),route_id uuid not null references public.fleet_routes(id) on delete cascade,update_type text not null,actor_user_id uuid references auth.users(id) on delete set null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now()); create index if not exists idx_fleet_route_updates_route_time on public.fleet_route_updates(route_id,created_at desc); alter table public.fleet_route_updates enable row level security; create policy fleet_route_updates_read_authenticated on public.fleet_route_updates for select to authenticated using (true); create or replace function public.publish_fleet_route_notification(p_route_id uuid,p_event_type text,p_title text,p_body text,p_payload jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare v_route public.fleet_routes%rowtype; v_event uuid; begin select * into v_route from public.fleet_routes where id=p_route_id; if not found then raise exception 'fleet route not found'; end if; insert into public.fleet_route_updates(route_id,update_type,actor_user_id,payload) values(p_route_id,p_event_type,auth.uid(),coalesce(p_payload,'{}'::jsonb)); select public.publish_intelligence_location_event(null,p_event_type,p_title,p_body,jsonb_build_object('fleet_route_id',p_route_id,'business_id',v_route.business_id)||coalesce(p_payload,'{}'::jsonb),0,'fleet:'||p_route_id::text||':'||p_event_type||':'||date_trunc('minute',now())::text) into v_event; return v_event; end; $$; create table if not exists public.enterprise_engagement_events (id uuid primary key default gen_random_uuid(),network_id uuid references public.enterprise_partner_networks(id) on delete cascade,event_type text not null,location_id uuid references public.locations(id) on delete set null,actor_user_id uuid references auth.users(id) on delete set null,payload jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now()); create index if not exists idx_enterprise_engagement_network_time on public.enterprise_engagement_events(network_id,occurred_at desc); alter table public.enterprise_engagement_events enable row level security; create policy enterprise_engagement_read_authenticated on public.enterprise_engagement_events for select to authenticated using(true);
